package ama.api;
import ama.contract.IdentityContracts.*;import ama.transcript.*;import ama.access.MeetingAccess;import ama.db.TransactionRunner;import jakarta.servlet.http.*;import java.io.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/meetings/{meetingId}/publications")
final class PublicationController {
 private final MinutesConfiguration.Runtime runtime;private final TransactionRunner tx;private final MeetingAccess access;private final JdbcPublicationQueries queries;
 PublicationController(MinutesConfiguration.Runtime runtime,TransactionRunner tx,MeetingAccess access){this(runtime,tx,access,null);}
 @org.springframework.beans.factory.annotation.Autowired PublicationController(MinutesConfiguration.Runtime runtime,TransactionRunner tx,MeetingAccess access,JdbcPublicationQueries queries){this.runtime=runtime;this.tx=tx;this.access=access;this.queries=queries;}
 @PostMapping ResponseEntity<byte[]> submit(@PathVariable String meetingId,HttpServletRequest request)throws IOException {
  byte[] raw;try(var in=request.getInputStream()){raw=in.readNBytes(65537);}if(raw.length>65536)throw new ama.contract.TranscriptContracts.Failure(413,"REQUEST_TOO_LARGE");var mapper=new com.fasterxml.jackson.databind.ObjectMapper(com.fasterxml.jackson.core.JsonFactory.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(com.fasterxml.jackson.core.StreamReadConstraints.builder().maxNestingDepth(4).maxStringLength(1024).maxNumberLength(19).build()).build()).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS);com.fasterxml.jackson.databind.JsonNode body;try{body=mapper.readTree(raw);}catch(com.fasterxml.jackson.core.JsonProcessingException malformed){throw new IllegalArgumentException("Malformed publication command");}if(body==null||!body.isObject())throw new IllegalArgumentException("Object required");body.fieldNames().forEachRemaining(name->{if(!Set.of("expectedRevision","expectedRevisionToken","confirmationId","providerId","libraryId","folderId").contains(name))throw new IllegalArgumentException("Unknown publication field");});long expected=HttpRevisionTokens.expected(body);var values=new HashMap<String,String>();for(String key:List.of("confirmationId","providerId","libraryId","folderId")){var value=body.get(key);if(value==null||!value.isTextual())throw new IllegalArgumentException("Publication field required");values.put(key,value.textValue());}var keys=Collections.list(request.getHeaders("Idempotency-Key"));if(keys.size()!=1)throw new IllegalArgumentException("One key required");JdbcProcessingIntake.key(keys.getFirst());
  var actor=((ResolvedSession)request.getAttribute(SessionSecurityFilter.SESSION)).actor();if(queries!=null){var replay=queries.lookup(actor,meetingId,"PUBLICATION_SUBMIT",keys.getFirst(),Long.toString(expected),values.get("confirmationId"),values.get("providerId"),values.get("libraryId"),values.get("folderId"));if(replay.isPresent())return read(replay.orElseThrow(),202);}if(runtime.publications()==null){tx.required(()->{access.require(access.lock(actor,meetingId),MeetingAccess.Action.EDIT);return null;});throw new ama.contract.TranscriptContracts.Failure(503,"PUBLICATION_NOT_INSTALLED");}
  var result=runtime.publications().submit(actor,meetingId,keys.getFirst(),expected,values.get("confirmationId"),values.get("providerId"),values.get("libraryId"),values.get("folderId"),UUID.randomUUID().toString());return ResponseEntity.status(202).contentType(MediaType.APPLICATION_JSON).header("Cache-Control","private, no-store").body(TranscriptWire.response(result,runtime.responseBytes()));
 }
 @PostMapping("/{publicationId}/local-recoveries") ResponseEntity<byte[]> recover(@PathVariable String meetingId,@PathVariable String publicationId,HttpServletRequest request)throws IOException {
  byte[] raw;try(var in=request.getInputStream()){raw=in.readNBytes(65537);}if(raw.length>65536)throw new ama.contract.TranscriptContracts.Failure(413,"REQUEST_TOO_LARGE");var mapper=new com.fasterxml.jackson.databind.ObjectMapper(com.fasterxml.jackson.core.JsonFactory.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(com.fasterxml.jackson.core.StreamReadConstraints.builder().maxNestingDepth(4).maxStringLength(1024).maxNumberLength(19).build()).build()).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS);com.fasterxml.jackson.databind.JsonNode body;try{body=mapper.readTree(raw);}catch(com.fasterxml.jackson.core.JsonProcessingException malformed){throw new IllegalArgumentException("Malformed publication command");}if(body==null||!body.isObject())throw new IllegalArgumentException("Object required");body.fieldNames().forEachRemaining(name->{if(!Set.of("expectedRevision","expectedRevisionToken","expectedPublicationRevision","expectedPublicationRevisionToken","taskId").contains(name))throw new IllegalArgumentException("Unknown local recovery field");});long expected=HttpRevisionTokens.expected(body);var publicationRevision=mapper.createObjectNode();if(body.has("expectedPublicationRevision"))publicationRevision.set("expectedRevision",body.get("expectedPublicationRevision"));if(body.has("expectedPublicationRevisionToken"))publicationRevision.set("expectedRevisionToken",body.get("expectedPublicationRevisionToken"));long expectedPublication=HttpRevisionTokens.expected(publicationRevision);if(!body.hasNonNull("taskId")||!body.get("taskId").isTextual())throw new IllegalArgumentException("Actual task required");var keys=Collections.list(request.getHeaders("Idempotency-Key"));if(keys.size()!=1)throw new IllegalArgumentException("One key required");JdbcProcessingIntake.key(keys.getFirst());var actor=((ResolvedSession)request.getAttribute(SessionSecurityFilter.SESSION)).actor();if(queries!=null){var replay=queries.lookup(actor,meetingId,"PUBLICATION_LOCAL_RECOVERY",keys.getFirst(),publicationId,body.get("taskId").textValue(),Long.toString(expected),Long.toString(expectedPublication));if(replay.isPresent())return read(replay.orElseThrow(),200);}if(runtime.localPublications()==null){tx.required(()->{access.require(access.lock(actor,meetingId),MeetingAccess.Action.EDIT);return null;});throw new ama.contract.TranscriptContracts.Failure(503,"PUBLICATION_LOCAL_RECOVERY_NOT_INSTALLED");}var result=runtime.localPublications().recover(actor,meetingId,publicationId,body.get("taskId").textValue(),keys.getFirst(),expected,expectedPublication,UUID.randomUUID().toString());return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).header("Cache-Control","private, no-store").body(TranscriptWire.response(result,runtime.responseBytes()));
 }

 @PostMapping("/{publicationId}/resubmissions") ResponseEntity<byte[]> resubmit(@PathVariable String meetingId,@PathVariable String publicationId,HttpServletRequest request)throws IOException {
  byte[] raw;try(var in=request.getInputStream()){raw=in.readNBytes(65537);}if(raw.length>65536)throw new ama.contract.TranscriptContracts.Failure(413,"REQUEST_TOO_LARGE");var mapper=new com.fasterxml.jackson.databind.ObjectMapper(com.fasterxml.jackson.core.JsonFactory.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(com.fasterxml.jackson.core.StreamReadConstraints.builder().maxNestingDepth(4).maxStringLength(1024).maxNumberLength(19).build()).build()).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS);com.fasterxml.jackson.databind.JsonNode body;try{body=mapper.readTree(raw);}catch(com.fasterxml.jackson.core.JsonProcessingException malformed){throw new IllegalArgumentException("Malformed publication command");}if(body==null||!body.isObject())throw new IllegalArgumentException("Object required");body.fieldNames().forEachRemaining(name->{if(!Set.of("expectedRevision","expectedRevisionToken","expectedPublicationRevision","expectedPublicationRevisionToken","confirmationId","providerId","libraryId","folderId").contains(name))throw new IllegalArgumentException("Unknown replacement field");});long expected=HttpRevisionTokens.expected(body);var publicationRevision=mapper.createObjectNode();if(body.has("expectedPublicationRevision"))publicationRevision.set("expectedRevision",body.get("expectedPublicationRevision"));if(body.has("expectedPublicationRevisionToken"))publicationRevision.set("expectedRevisionToken",body.get("expectedPublicationRevisionToken"));long expectedPublication=HttpRevisionTokens.expected(publicationRevision);var values=new HashMap<String,String>();for(String key:List.of("confirmationId","providerId","libraryId","folderId")){var value=body.get(key);if(value==null||!value.isTextual())throw new IllegalArgumentException("Replacement field required");values.put(key,value.textValue());}var keys=Collections.list(request.getHeaders("Idempotency-Key"));if(keys.size()!=1)throw new IllegalArgumentException("One key required");JdbcProcessingIntake.key(keys.getFirst());var actor=((ResolvedSession)request.getAttribute(SessionSecurityFilter.SESSION)).actor();if(queries!=null){var replay=queries.lookup(actor,meetingId,"PUBLICATION_RESUBMIT",keys.getFirst(),publicationId,Long.toString(expected),Long.toString(expectedPublication),values.get("confirmationId"),values.get("providerId"),values.get("libraryId"),values.get("folderId"));if(replay.isPresent())return read(replay.orElseThrow(),202);}if(runtime.publications()==null){tx.required(()->{access.require(access.lock(actor,meetingId),MeetingAccess.Action.EDIT);return null;});throw new ama.contract.TranscriptContracts.Failure(503,"PUBLICATION_NOT_INSTALLED");}var result=runtime.publications().resubmit(actor,meetingId,publicationId,keys.getFirst(),expected,expectedPublication,values.get("confirmationId"),values.get("providerId"),values.get("libraryId"),values.get("folderId"),UUID.randomUUID().toString());return ResponseEntity.status(202).contentType(MediaType.APPLICATION_JSON).header("Cache-Control","private, no-store").body(TranscriptWire.response(result,runtime.responseBytes()));
 }

 @PostMapping("/{publicationId}/zero-effect-retries") ResponseEntity<byte[]> retryZeroEffect(@PathVariable String meetingId,@PathVariable String publicationId,HttpServletRequest request)throws IOException {
  byte[] raw;try(var in=request.getInputStream()){raw=in.readNBytes(65537);}if(raw.length>65536)throw new ama.contract.TranscriptContracts.Failure(413,"REQUEST_TOO_LARGE");var mapper=new com.fasterxml.jackson.databind.ObjectMapper(com.fasterxml.jackson.core.JsonFactory.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(com.fasterxml.jackson.core.StreamReadConstraints.builder().maxNestingDepth(4).maxStringLength(1024).maxNumberLength(19).build()).build()).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS);com.fasterxml.jackson.databind.JsonNode body;try{body=mapper.readTree(raw);}catch(com.fasterxml.jackson.core.JsonProcessingException malformed){throw new IllegalArgumentException("Malformed exact retry command");}if(body==null||!body.isObject())throw new IllegalArgumentException("Object required");body.fieldNames().forEachRemaining(name->{if(!Set.of("expectedRevision","expectedRevisionToken","expectedPublicationRevision","expectedPublicationRevisionToken","expectedExecutionNo","expectedExecutionNoToken").contains(name))throw new IllegalArgumentException("Unknown exact retry field");});long expected=HttpRevisionTokens.expected(body);long expectedPublication=retryCounter(mapper,body,"expectedPublicationRevision"),expectedExecution=retryCounter(mapper,body,"expectedExecutionNo");if(expectedExecution<1)throw new IllegalArgumentException("Positive execution number required");var keys=Collections.list(request.getHeaders("Idempotency-Key"));if(keys.size()!=1)throw new IllegalArgumentException("One key required");JdbcProcessingIntake.key(keys.getFirst());var actor=actor(request);
  if(queries!=null){var replay=queries.lookup(actor,meetingId,"PUBLICATION_ZERO_EFFECT_RETRY",keys.getFirst(),publicationId,Long.toString(expected),Long.toString(expectedPublication),Long.toString(expectedExecution));if(replay.isPresent())return read(replay.orElseThrow(),202);}
  if(runtime.publications()==null){tx.required(()->{access.require(access.lock(actor,meetingId),MeetingAccess.Action.EDIT);return null;});throw new ama.contract.TranscriptContracts.Failure(503,"PUBLICATION_NOT_INSTALLED");}
  return read(runtime.publications().retryZeroEffect(actor,meetingId,publicationId,keys.getFirst(),expected,expectedPublication,expectedExecution,UUID.randomUUID().toString()),202);
 }
 private static long retryCounter(com.fasterxml.jackson.databind.ObjectMapper mapper,com.fasterxml.jackson.databind.JsonNode body,String name){var value=mapper.createObjectNode();if(body.has(name))value.set("expectedRevision",body.get(name));if(body.has(name+"Token"))value.set("expectedRevisionToken",body.get(name+"Token"));return HttpRevisionTokens.expected(value);}

 @GetMapping("/current") ResponseEntity<byte[]> current(@PathVariable String meetingId,HttpServletRequest request)throws IOException{return read(query().current(actor(request),meetingId));}
 @GetMapping("/{publicationId}") ResponseEntity<byte[]> detail(@PathVariable String meetingId,@PathVariable String publicationId,HttpServletRequest request)throws IOException{return read(query().detail(actor(request),meetingId,publicationId));}
 @GetMapping("/{publicationId}/submissions") ResponseEntity<byte[]> submissions(@PathVariable String meetingId,@PathVariable String publicationId,@RequestParam(defaultValue="20") int limit,@RequestParam(required=false) String cursor,HttpServletRequest request)throws IOException{return read(query().history(actor(request),meetingId,publicationId,true,limit,cursor));}
 @GetMapping("/{publicationId}/attempts") ResponseEntity<byte[]> attempts(@PathVariable String meetingId,@PathVariable String publicationId,@RequestParam(defaultValue="20") int limit,@RequestParam(required=false) String cursor,HttpServletRequest request)throws IOException{return read(query().history(actor(request),meetingId,publicationId,false,limit,cursor));}
 private JdbcPublicationQueries query(){if(queries==null)throw new ama.contract.TranscriptContracts.Failure(503,"PUBLICATION_READ_UNAVAILABLE");return queries;}
 private static Actor actor(HttpServletRequest request){return ((ResolvedSession)request.getAttribute(SessionSecurityFilter.SESSION)).actor();}
 private ResponseEntity<byte[]> read(Object result)throws IOException{return read(result,200);}
 private ResponseEntity<byte[]> read(Object result,int status)throws IOException{return ResponseEntity.status(status).contentType(MediaType.APPLICATION_JSON).header("Cache-Control","private, no-store").body(TranscriptWire.response(result,runtime.responseBytes()));}

}
